t = int(input())
for i in range(t):
	(n, m, k) = map(int, input().split())
	l1 = list(map(int, input().split()))
	c = 0
	d = {}
	if n == 0:
		print(0)
	else:
		for i in range(k):
			if l1[i] in d:
				d[l1[i]] += 1
			elif l1[i] <= n + 1:
				d[l1[i]] = 1
		l2 = []
		for i in d.keys():
			if d[i] > 1:
				c += 1
				l2.append(i)
		print(c, end=' ')
		l = len(l2)
		l2.sort()
		for g in range(l):
			print(l2[g], end=' ')
		print()
